struct DynamicAABBTreeNode final
{
    SpatialAABB TightBounds = SpatialAABB::Empty();
    SpatialAABB FatBounds = SpatialAABB::Empty();

    SpatialIndex Parent = SpatialInvalidIndex;
    SpatialIndex Left = SpatialInvalidIndex;
