    delta =
        delta.Normalized();

    const float sinHalf =
        Vec3f{
            delta.x,
            delta.y,
            delta.z
        }.Length();

    if (sinHalf < 1.0e-7f)
    {
        b.State.AngularVelocity =
            Vec3f::Zero();
